def plugin_class
      if @plugin_class.nil?
        Object.module_eval(@source)
        const_names = @class_name.split('::')
        @plugin_class = const_names.inject(Kernel) do |const, const_name|
          const.const_get(const_name)
        end
      end
      @plugin_class
