def throttling?(shape)
      shape['retryable'] && shape['retryable'].kind_of?(Hash) && shape['retryable']['throttling']
    end

def custom_error_class(shape)
      return unless (custom_error_name = shape.dig('error', 'code'))

      custom_error_name
    end

